// File: /functions/api/admin/_amazonInventoryMatches.js
// Brief description: Private admin-side Amazon Business CSV match data used to backfill
// tool/supply Amazon links, unit costs, supplier details, and purchase notes into D1.
// This module is imported by admin API functions and is not a public static data file.

// Build 233: keep the private one-time Amazon CSV reference compressed at Worker startup.
// Only an authenticated inventory route expands its requested area.
const AMAZON_INVENTORY_MATCHES_GZIP_BY_AREA = {
  "supplies": "",
  "toolshed": "",
};

function normalizeKey(value) {
  return String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function toNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function inferPackUsageFromText(...values) {
  const text = values.map((value) => String(value || '')).join(' ').replace(/\s+/g, ' ').trim();
  const lower = text.toLowerCase();
  if (!lower) return null;

  const hasLiquidUnit = /\b(ml|millilitre|milliliter|litre|liter|oz|ounce|ounces|fl\s*oz|gallon|quart)\b/i.test(lower);
  if (hasLiquidUnit && !/\b(sheet|sheets|roll|rolls|piece|pieces|pcs|pack|packs|count|ct|mask|masks)\b/i.test(lower)) {
    return null;
  }

  const patterns = [
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:sheets?|sheet)\b/i, unit: 'sheet' },
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:pcs|pieces?|piece)\b/i, unit: 'piece' },
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:counts?|count|ct)\b/i, unit: 'unit' },
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:rolls?|roll)\b/i, unit: 'roll' },
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:masks?|mask)\b/i, unit: 'mask' },
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:pairs?|pair)\b/i, unit: 'pair' },
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:wicks?|wick)\b/i, unit: 'wick' },
    { re: /(?:^|\b)(\d{1,5})\s*(?:x\s*)?(?:bags?|bag)\b/i, unit: 'bag' }
  ];

  for (const pattern of patterns) {
    const match = lower.match(pattern.re);
    if (match) {
      const count = Math.max(1, Math.round(toNumber(match[1], 1)));
      return { stock_unit_label: 'package', usage_unit_label: pattern.unit, usage_units_per_stock_unit: count };
    }
  }

  const packMatch = lower.match(/(?:^|\b)(\d{1,5})\s*(?:pack|pk)\b/i) || lower.match(/(?:pack\s+of|package\s+of)\s*(\d{1,5})\b/i);
  if (packMatch) {
    const count = Math.max(1, Math.round(toNumber(packMatch[1], 1)));
    let unit = 'unit';
    if (/\bsheets?\b/i.test(lower)) unit = 'sheet';
    else if (/\bmasks?\b/i.test(lower)) unit = 'mask';
    else if (/\brolls?\b/i.test(lower)) unit = 'roll';
    else if (/\bwicks?\b/i.test(lower)) unit = 'wick';
    return { stock_unit_label: 'package', usage_unit_label: unit, usage_units_per_stock_unit: count };
  }

  return null;
}

const AMAZON_MATCH_REGISTRIES = new Map();
const AMAZON_MATCH_LOADS = new Map();

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

async function expandAmazonMatchRows(encoded) {
  if (typeof DecompressionStream !== 'function') {
    throw new Error('This Worker runtime does not support gzip payload expansion.');
  }
  const stream = new Blob([decodeBase64(encoded)]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
}

async function getAmazonMatchRegistry(areaKey) {
  if (AMAZON_MATCH_REGISTRIES.has(areaKey)) return AMAZON_MATCH_REGISTRIES.get(areaKey);
  if (AMAZON_MATCH_LOADS.has(areaKey)) return AMAZON_MATCH_LOADS.get(areaKey);
  const encoded = AMAZON_INVENTORY_MATCHES_GZIP_BY_AREA[areaKey];
  if (!encoded) return null;

  const loading = expandAmazonMatchRows(encoded).then((areaRows) => {
    const byIndex = new Map(areaRows.map((row) => [Number(row.inventory_index || 0), row]));
    const byName = new Map();
    for (const row of areaRows) {
      const key = normalizeKey(row.inventory_name);
      if (key && !byName.has(key)) byName.set(key, row);
    }
    const registry = { byIndex, byName };
    AMAZON_MATCH_REGISTRIES.set(areaKey, registry);
    AMAZON_MATCH_LOADS.delete(areaKey);
    return registry;
  }).catch((error) => {
    AMAZON_MATCH_LOADS.delete(areaKey);
    throw error;
  });
  AMAZON_MATCH_LOADS.set(areaKey, loading);
  return loading;
}

export async function getAmazonInventoryMatch(area, index, inventoryName = '') {
  const areaKey = normalizeKey(area);
  const registry = await getAmazonMatchRegistry(areaKey);
  if (!registry) return null;
  const byIndex = registry.byIndex.get(Number(index || 0));
  if (byIndex) return byIndex;
  return registry.byName.get(normalizeKey(inventoryName)) || null;
}

function parseRecord(sourceRecordJson) {
  if (!sourceRecordJson) return {};
  if (typeof sourceRecordJson === 'object') return sourceRecordJson || {};
  try {
    return JSON.parse(String(sourceRecordJson || '{}')) || {};
  } catch {
    return {};
  }
}

export function extractAmazonInventoryFields(sourceRecordJson, fallbackKind = '') {
  const source = parseRecord(sourceRecordJson);
  const embedded = source.amazon_match && typeof source.amazon_match === 'object' ? source.amazon_match : source;
  const kind = normalizeKey(fallbackKind || source.item_kind || source.source_type || '');

  const latestPurchasePpuCad = toNumber(embedded.latest_purchase_ppu_cad ?? source.amazon_latest_purchase_ppu_cad, 0);
  const latestItemNetTotalCad = toNumber(embedded.latest_item_net_total_cad ?? source.amazon_latest_item_net_total_cad, 0);
  const landedUnitCostCad = toNumber(embedded.landed_unit_cost_cad ?? source.amazon_landed_unit_cost_cad, 0);
  const unitCostCents = Math.max(0, Math.round(toNumber(embedded.unit_cost_cents ?? source.unit_cost_cents, 0))) ||
    Math.max(0, Math.round((latestPurchasePpuCad || landedUnitCostCad || latestItemNetTotalCad || 0) * 100));

  const inferredPack = inferPackUsageFromText(
    embedded.amazon_title,
    embedded.inventory_name,
    source.amazon_title,
    source.inventory_name,
    source.item_name_suggested,
    source.name
  );

  const stockUnitLabel = inferredPack?.stock_unit_label ||
    String(embedded.stock_unit_label || source.stock_unit_label || (kind === 'tool' ? 'tool' : 'package')).trim() ||
    (kind === 'tool' ? 'tool' : 'package');
  const usageUnitLabel = inferredPack?.usage_unit_label ||
    String(embedded.usage_unit_label || source.usage_unit_label || (kind === 'tool' ? 'use' : 'unit')).trim() ||
    (kind === 'tool' ? 'use' : 'unit');
  const usageUnitsPerStockUnit = Math.max(1, inferredPack?.usage_units_per_stock_unit || toNumber(embedded.usage_units_per_stock_unit ?? source.usage_units_per_stock_unit, 1));

  return {
    amazon_match_status: String(embedded.match_status || source.amazon_match_status || '').trim(),
    amazon_match_score: toNumber(embedded.match_score ?? source.amazon_match_score, 0),
    amazon_score_margin_vs_next: toNumber(embedded.score_margin_vs_next ?? source.amazon_score_margin_vs_next, 0),
    amazon_token_overlap_pct: toNumber(embedded.token_overlap_pct ?? source.amazon_token_overlap_pct, 0),
    amazon_asin: String(embedded.amazon_asin || source.amazon_asin || '').trim(),
    amazon_url: String(embedded.amazon_url || source.amazon_url || source.amazon_search_url || '').trim(),
    amazon_title: String(embedded.amazon_title || source.amazon_title || '').trim(),
    amazon_brand: String(embedded.amazon_brand || source.amazon_brand || source.brand_guess || source.brand || '').trim(),
    amazon_category: String(embedded.amazon_category || source.amazon_category || '').trim(),
    seller_name: String(embedded.seller_name || source.seller_name || '').trim(),
    first_purchase_date: String(embedded.first_purchase_date || source.first_purchase_date || '').trim(),
    latest_purchase_date: String(embedded.latest_purchase_date || source.latest_purchase_date || '').trim(),
    latest_order_id: String(embedded.latest_order_id || source.latest_order_id || '').trim(),
    latest_purchase_ppu_cad: latestPurchasePpuCad,
    latest_item_net_total_cad: latestItemNetTotalCad,
    matched_asin_order_count: Math.max(0, Math.round(toNumber(embedded.matched_asin_order_count ?? source.matched_asin_order_count, 0))),
    matched_asin_total_quantity: Math.max(0, toNumber(embedded.matched_asin_total_quantity ?? source.matched_asin_total_quantity, 0)),
    matched_asin_total_item_subtotal_cad: toNumber(embedded.matched_asin_total_item_subtotal_cad ?? source.matched_asin_total_item_subtotal_cad, 0),
    matched_asin_total_shipping_cad: toNumber(embedded.matched_asin_total_shipping_cad ?? source.matched_asin_total_shipping_cad, 0),
    matched_asin_total_promo_cad: toNumber(embedded.matched_asin_total_promo_cad ?? source.matched_asin_total_promo_cad, 0),
    matched_asin_total_federal_tax_cad: toNumber(embedded.matched_asin_total_federal_tax_cad ?? source.matched_asin_total_federal_tax_cad, 0),
    matched_asin_total_provincial_tax_cad: toNumber(embedded.matched_asin_total_provincial_tax_cad ?? source.matched_asin_total_provincial_tax_cad, 0),
    matched_asin_total_regulatory_fee_cad: toNumber(embedded.matched_asin_total_regulatory_fee_cad ?? source.matched_asin_total_regulatory_fee_cad, 0),
    matched_asin_total_net_cad: toNumber(embedded.matched_asin_total_net_cad ?? source.matched_asin_total_net_cad, 0),
    landed_unit_cost_cad: landedUnitCostCad,
    unit_cost_cents: unitCostCents,
    stock_unit_label: stockUnitLabel,
    usage_unit_label: usageUnitLabel,
    usage_units_per_stock_unit: usageUnitsPerStockUnit,
    source_order_ids_for_asin: String(embedded.source_order_ids_for_asin || source.source_order_ids_for_asin || '').trim()
  };
}

export function buildAmazonInventoryNote(fields = {}) {
  const parts = [];
  if (fields.amazon_match_status) parts.push(`Amazon CSV ${fields.amazon_match_status}`);
  if (fields.amazon_match_score) parts.push(`score ${Number(fields.amazon_match_score).toFixed(2)}%`);
  if (fields.amazon_asin) parts.push(`ASIN ${fields.amazon_asin}`);
  if (fields.latest_order_id) parts.push(`latest order ${fields.latest_order_id}`);
  if (fields.latest_purchase_date) parts.push(`latest purchase ${fields.latest_purchase_date}`);
  if (fields.latest_purchase_ppu_cad) parts.push(`latest PPU CAD ${Number(fields.latest_purchase_ppu_cad).toFixed(2)}`);
  if (fields.latest_item_net_total_cad) parts.push(`latest item net CAD ${Number(fields.latest_item_net_total_cad).toFixed(2)}`);
  return parts.join(' | ');
}
